  if (body.length === 0) return { ok: false, reason: "mesej kosong" };
  if (body.length < MIN_LEN) return { ok: false, reason: "mesej terlalu pendek" };
  if (body.length > MAX_LEN) return { ok: false, reason: `mesej terlalu panjang (max ${MAX_LEN})` };
