  // 3) Rate limit
  const rl = checkRate(senderJid);
  if (!rl.ok) {
    return { ok: false, reply: `⏳ Tunggu ${rl.retry}s sebelum broadcast lagi.` };
  }
  // 4) Recipients
  const targets = getRecipients();
  if (targets.length === 0) {
    return { ok: false, reply: "⚠️ Tiada penerima dikonfigurasi." };
  }
