## 1️⃣ Pepijat `!broadcastspam`
**SEBELUM (contoh):**
```js
// handlers/message.js
if (body.startsWith("!broadcast")) {
  return handleBroadcast(msg, body.slice("!broadcast".length).trim());
}
```
**SELEPAS (contoh):**
```js
// handlers/message.js
const PREFIX = "!";
const CMD = body.slice(PREFIX.length).split(/\s+/)[0]; // "broadcastspam"
if (CMD === "broadcast") {
  const args = body.slice(PREFIX.length + CMD.length).trim();
  return handleBroadcast(msg, args);
}
```
**Sebab:** padanan **token penuh**, bukan `startsWith`. `!broadcastspam` → CMD = `"broadcastspam"` → tak lulus.
---
## 2️⃣ Bezakan JID penghantar vs kumpulan
**SEBELUM (contoh):**
```js
const senderJid = msg.key.remoteJid; // salah utk kumpulan
```
**SELEPAS (contoh):**
```js
// lib/jid.js
function getSenderJid(msg) {
  const key = msg?.key ?? {};
  const isGroup = typeof key.remoteJid === "string" && key.remoteJid.endsWith("@g.us");
  const jid = isGroup ? key.participant : key.remoteJid;
  if (!jid) return null;
  return jid.split(":")[0].split("@")[0] + "@s.whatsapp.net";
}
```
**Sebab:** dalam kumpulan, `remoteJid` = JID kumpulan; `participant` = penghantar sebenar.
---
## 3️⃣ Hadkan broadcast kepada owner
**SEBELUM (contoh):**
```js
async function handleBroadcast(msg, text) {
  // terus hantar
}
```
**SELEPAS (contoh):**
```js
// lib/owner.js
const OWNER_JIDS = new Set(
  (process.env.OWNER_JIDS || "").split(",").map(s => s.trim()).filter(Boolean)
);
function isOwner(jid) {
  return !!jid && OWNER_JIDS.has(jid);
}
// commands/broadcast.js
async function handleBroadcast(msg, text) {
  const sender = getSenderJid(msg);
  if (!isOwner(sender)) {
    return reply(msg, "❌ Arahan ini hanya untuk owner.");
  }
  if (!text) return reply(msg, "⚠️ Mesej kosong.");
  // ... sambung
}
```
**Sebab:** semakan dibuat **sebelum** sebarang penghantaran, guna JID penghantar sebenar.
