"use strict";
const { handleBroadcast } = require("../commands/broadcast");
const PREFIX = "!";
function parseCommand(body, prefix = PREFIX) {
  if (typeof body !== "string" || !body.startsWith(prefix)) return null;
  const rest = body.slice(prefix.length);
  const m = rest.match(/^(\S+)(?:\s+([\s\S]*))?$/);
  if (!m) return null;
  return { cmd: m[1], args: (m[2] ?? "").trim() };
}
async function handleMessage({ sock, msg, reply, broadcastTargets = [] }) {
  const body =
    msg?.message?.conversation ||
    msg?.message?.extendedTextMessage?.text ||
    "";
  const parsed = parseCommand(body);
  if (!parsed) return { handled: false };
  if (parsed.cmd === "broadcast") {
    return handleBroadcast({
      sock,
      msg,
      args: parsed.args,
      reply,
      targets: broadcastTargets,
    });
  }
  return { handled: false, cmd: parsed.cmd };
}
module.exports = { parseCommand, handleMessage };
```
