"use strict";
const { normalizeJid } = require("./jid");
function getOwnerJids() {
  const raw = process.env.OWNER_JIDS || "";
  return raw
    .split(",")
    .map((s) => normalizeJid(s.trim()))
    .filter(Boolean);
}
function isOwner(jid) {
  const norm = normalizeJid(jid);
  if (!norm) return false;
  return getOwnerJids().includes(norm);
}
