"use strict";
function isDryRun() {
  return String(process.env.DRY_RUN || "0") === "1";
}
async function safeSend(sock, jid, payload) {
  if (!sock || typeof sock.sendMessage !== "function") {
    throw new Error("safeSend: sock.sendMessage tidak tersedia");
  }
  if (isDryRun()) {
    return { dryRun: true, jid, payload };
  }
  return sock.sendMessage(jid, payload);
}
module.exports = { safeSend, isDryRun };
```
