## 4️⃣ `commands/broadcast.js`
```js
"use strict";
const { getSenderJid } = require("../lib/jid");
const { isOwner } = require("../lib/owner");
const { safeSend } = require("../lib/send");
async function handleBroadcast({ sock, msg, args, reply, targets = [] }) {
  const sender = getSenderJid(msg);
  if (!isOwner(sender)) {
    await reply(msg, "❌ Arahan ini hanya untuk owner.");
    return { ok: false, reason: "not_owner" };
  }
  const text = (args || "").trim();
  if (!text) {
    await reply(msg, "⚠️ Mesej broadcast kosong.");
    return { ok: false, reason: "empty" };
  }
  const results = [];
  for (const target of targets) {
    try {
      const res = await safeSend(sock, target, { text });
      results.push({ target, ok: true, res });
    } catch (err) {
      results.push({ target, ok: false, error: String(err?.message || err) });
    }
  }
  await reply(msg, `✅ Broadcast selesai: ${results.length} sasaran.`);
  return { ok: true, results };
}
module.exports = { handleBroadcast };
```
