const CMD = 'broadcast';
async function runBroadcast({ senderJid, targets, text, isGroup, dryRun }) {
  if (!isOwner(senderJid)) {
    return { ok: false, reason: 'not_owner', sent: 0 };
  }
  if (isGroup) {
    return { ok: false, reason: 'group_not_allowed', sent: 0 };
