```js
const { runBroadcast } = require('../commands/broadcast');
// Parser sebenar — satu-satunya sumber kebenaran
function parseCommand(body) {
  if (typeof body !== 'string') return null;
  const trimmed = body.trim();
  if (!trimmed.startsWith('!')) return null;
  const firstSpace = trimmed.indexOf(' ');
  const head = firstSpace === -1 ? trimmed : trimmed.slice(0, firstSpace);
  const args = firstSpace === -1 ? '' : trimmed.slice(firstSpace + 1).trim();
  const name = head.slice(1).toLowerCase();
  if (!name) return null;
  return { name, args };
}
async function handleMessage(ctx) {
  const { body, senderJid, isGroup, dryRun } = ctx;
  const parsed = parseCommand(body);
  if (!parsed) return { handled: false };
  // Tolak !broadcastspam — hanya 'broadcast' sah
  if (parsed.name !== 'broadcast') {
    return { handled: false, reason: 'unknown_command' };
  }
  const targets = parsed.args ? parsed.args.split(',').map(s => s.trim()).filter(Boolean) : [];
  const text = ctx.text || 'Hello';
  const result = await runBroadcast({ senderJid, targets, text, isGroup, dryRun });
  return { handled: true, result };
}
module.exports = { parseCommand, handleMessage };
